std::string s = "apple pie is delicious";

// 1. Positional replacement (pos, len, replacement_str)
s.replace(0, 5, "cherry");
// s: "cherry pie is delicious"

// 2. Replacement with N chars (pos, len, count, char)
s.replace(10, 2, 4, '!');
// s: "cherry pie!!!! delicious" (Replaced 'is')

// 3. Using iterators (range, replacement_str)
auto it_start = s.begin() + 10;
auto it_end = s.begin() + 14;
s.replace(it_start, it_end, "IS");
// s: "cherry pie IS delicious"
